checkRuns.command:
cat > test/site.test.ts <<'EOF'
import { expect, it } from 'bun:test'
import { testSite } from 'kay/test'
import { send } from '../src/routes/contact.kay'

const site = await testSite()

it('refuses a bad message with every error', async () => {
  const refused = await site.refusal(send, { name: ' ', email: '', message: 'short' })

  expect(refused.status).toBe(422)
  expect(refused.data).toEqual({ errors: {
    name: 'Name is required.',
    email: 'Email is required.',
    message: 'Message must be at least 20 characters.',
  } })
})

it('thanks the sender by trimmed name', async () => {
  const result = await site.call(send, { name: ' Ann ', email: 'ann@example.com', message: 'A message long enough to pass.' })

  expect(result).toEqual({ name: 'Ann' })
})

it('answers an unknown book with the 404 page', async () => {
  const page = await site.visit('/books/nope')

  expect(page.status).toBe(404)
  expect(page.text('h1')).toBe('Not found')
})
EOF
bun test 2>&1 | tail -8; bun run check 2>&1 | tail -3; bun run fmt 2>&1 | tail -2; bun run build 2>&1 | grep -E -i 'error|fail|warn'; git status --short
